window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f9a964e9935b5939"]={"versions": [{"id": "FIG-f9a964e9935b5939", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (<code>stm Can Controller State Machine</code>) für den CAN-Controller im AUTOSAR Classic CAN Driver (<code>Can</code>). Es beschreibt die zulässigen Controller-Betriebszustände und Transitionen auf Treiberebene unterhalb des CAN Interface (<code>CanIf</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Pseudo-Initialzustand (ausgehend von <code>PowerOff</code> über <code>PowerON reset</code>)\n</li><li>Betriebszustände: <code>UNINT</code>, <code>STOPPED</code>, <code>STARTED</code>, <code>SLEEP</code>\n</li><li>Schnittstellen/Ereignisse: <code>PowerON reset</code>, unbeschriftete Transitionen zwischen den Zuständen sowie Selbsttransitionen an <code>STOPPED</code> und <code>SLEEP</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Nach <code>PowerON reset</code> wechselt der CAN-Controller aus dem Initialzustand in <code>UNINT</code>.\n</li><li>Von <code>UNINT</code> führt eine gerichtete Transition in den Zustand <code>STOPPED</code>.\n</li><li>Zwischen <code>STOPPED</code> und <code>STARTED</code> existieren bidirektionale Transitionen.\n</li><li>Zwischen <code>STOPPED</code> und <code>SLEEP</code> existieren bidirektionale Transitionen.\n</li><li>An den Zuständen <code>STOPPED</code> und <code>SLEEP</code> sind jeweils Selbsttransitionen (interne/externe Re-Entry-Schleifen) definiert.\n</li><li>Es existiert keine Rücktransition aus <code>STOPPED</code>, <code>STARTED</code> oder <code>SLEEP</code> zurück nach <code>UNINT</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert normativ die Zustandswechsel des CAN-Controllers. Es bildet die Grundlage für die Implementierung der Treiber-Zustandsverwaltung; ohne Deinitialisierungs-Transitionen verbleibt der Controller nach dem Verlassen von <code>UNINT</code> dauerhaft im initialisierten Zyklus aus <code>STOPPED</code>, <code>STARTED</code> und <code>SLEEP</code>.</p>"}, {"id": "FIG-a96bd0383728793a", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm für den CAN-Controller im AUTOSAR Classic CAN Driver (<code>Can</code>). Es beschreibt die zulässigen Controller-Betriebszustände und Deinitialisierungs-Transitionen auf Treiberebene unterhalb des CAN Interface (<code>CanIf</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Pseudo-Initialzustand (Ereignis: <code>PowerON reset</code>)\n</li><li>Betriebszustände: <code>UNINIT</code>, <code>STOPPED</code>, <code>STARTED</code>, <code>SLEEP</code>\n</li><li>Schnittstellen/API-Trigger: <code>PowerON reset</code>, <code>Can_DeInit()</code>, unbeschriftete Zustandstransitionen sowie Selbsttransitionen an <code>STOPPED</code> und <code>SLEEP</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Auslösend durch <code>PowerON reset</code> tritt der Controller in den Zustand <code>UNINIT</code> ein.\n</li><li>Aus <code>UNINIT</code> führt eine Transition in den Zustand <code>STOPPED</code>.\n</li><li>Zwischen <code>STOPPED</code> und <code>STARTED</code> bestehen bidirektionale Transitionen.\n</li><li>Zwischen <code>STOPPED</code> und <code>SLEEP</code> bestehen bidirektionale Transitionen.\n</li><li>Sowohl <code>STOPPED</code> als auch <code>SLEEP</code> besitzen Selbsttransitionen.\n</li><li>Über den API-Aufruf <code>Can_DeInit()</code> kann der Controller sowohl aus dem Zustand <code>STOPPED</code> als auch aus dem Zustand <code>SLEEP</code> zurück in den Zustand <code>UNINIT</code> überführt werden.\n</li><li>Aus <code>STARTED</code> existiert keine direkte Deinitialisierungs-Transition nach <code>UNINIT</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifiziert das normative Zustandsverhalten des CAN-Controllers einschließlich der Deinitialisierung. Für Entwickler bedeutet dies, dass <code>Can_DeInit()</code> nur in den Zuständen <code>STOPPED</code> und <code>SLEEP</code> zulässig ist und den Controller in <code>UNINIT</code> versetzt; vor einer Deinitialisierung aus <code>STARTED</code> muss der Controller zunächst nach <code>STOPPED</code> überführt werden.</p>"}, {"id": "FIG-4a2ae66614641447", "releases": ["R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm für den CAN-Controller im AUTOSAR Classic CAN Driver (<code>Can</code>). Es beschreibt die zulässigen Controller-Betriebszustände und Deinitialisierungs-Transitionen auf Treiberebene unterhalb des CAN Interface (<code>CanIf</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Pseudo-Initialzustand (Ereignis: <code>PowerON reset</code>)\n</li><li>Betriebszustände: <code>UNINIT</code>, <code>STOPPED</code>, <code>STARTED</code>, <code>SLEEP</code>\n</li><li>Schnittstellen/API-Trigger: <code>PowerON reset</code>, <code>Can_DeInit()</code>, unbeschriftete Zustandstransitionen sowie Selbsttransitionen an <code>STOPPED</code> und <code>SLEEP</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li>Auslösend durch <code>PowerON reset</code> tritt der Controller in den Zustand <code>UNINIT</code> ein.\n</li><li>Aus <code>UNINIT</code> führt eine Transition in den Zustand <code>STOPPED</code>.\n</li><li>Zwischen <code>STOPPED</code> und <code>STARTED</code> bestehen bidirektionale Transitionen.\n</li><li>Zwischen <code>STOPPED</code> und <code>SLEEP</code> bestehen bidirektionale Transitionen.\n</li><li>Sowohl <code>STOPPED</code> als auch <code>SLEEP</code> besitzen Selbsttransitionen.\n</li><li>Über den API-Aufruf <code>Can_DeInit()</code> kann der Controller sowohl aus dem Zustand <code>STOPPED</code> als auch aus dem Zustand <code>SLEEP</code> zurück in den Zustand <code>UNINIT</code> überführt werden.\n</li><li>Aus <code>STARTED</code> existiert keine direkte Deinitialisierungs-Transition nach <code>UNINIT</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifiziert das normative Zustandsverhalten des CAN-Controllers einschließlich der Deinitialisierung. Für Entwickler bedeutet dies, dass <code>Can_DeInit()</code> nur in den Zuständen <code>STOPPED</code> und <code>SLEEP</code> zulässig ist und den Controller in <code>UNINIT</code> versetzt; vor einer Deinitialisierung aus <code>STARTED</code> muss der Controller zunächst nach <code>STOPPED</code> überführt werden.</p>"}], "trans": [{"from": "FIG-f9a964e9935b5939", "to": "FIG-a96bd0383728793a", "fr": "R4.0.3", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung der Transition von <code>STOPPED</code> nach <code>UNINIT</code> mit dem Trigger <code>Can_DeInit()</code>.\n</li><li>Ergänzung der Transition von <code>SLEEP</code> nach <code>UNINIT</code> mit dem Trigger <code>Can_DeInit()</code>.\n</li><li>Korrektur der Zustandsbezeichnung von <code>UNINT</code> zu <code>UNINIT</code>.\n</li><li>Entfernung des UML-Rahmens (<code>stm Can Controller State Machine</code>) und der Pseudo-Zustandsbezeichnung <code>PowerOff</code> oberhalb des Initial-Zustands.\n</li></ul>"}, {"from": "FIG-a96bd0383728793a", "to": "FIG-4a2ae66614641447", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
